import requests, sys, uuid, time

BASE = '{{TESTVDB_DB_URL}}'

# Setup: create a collection with data first
c = 'test_matrix_' + uuid.uuid4().hex[:8]

# Create collection with named vectors (need 'using' param)
r = requests.put(f'{BASE}/collections/{c}', json={
    'vectors': {
        'text': {'size': 4, 'distance': 'Cosine'},
        'image': {'size': 4, 'distance': 'Cosine'}
    }
})
if r.status_code not in (200, 201):
    print(f'setup create failed: {r.status_code} {r.text}')
    sys.exit(0)
time.sleep(0.5)

# Insert some points with both vector names
points = [
    {'id': i+1, 'vector': {'text': [0.1*i, 0.2*i, 0.3*i, 0.4*i], 'image': [0.2*i, 0.3*i, 0.4*i, 0.5*i]}}
    for i in range(10)
]
r = requests.put(f'{BASE}/collections/{c}/points', json={'points': points})
time.sleep(0.5)

# TEST 1: using=null
print("=== TEST 1: using=null ===")
r = requests.post(f'{BASE}/collections/{c}/points/search/matrix/pairs', json={
    'using': None,
    'limit': 5,
    'sample': 5
})
print(f'Status: {r.status_code}, Body: {r.text[:200]}')
if r.status_code == 200:
    print('[DEFECT: ILLEGAL_SUCCESS] using=null was accepted')
    sys.exit(1)
else:
    print('OK: using=null correctly rejected')

